import sys,json,torch
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'experiments'))
from zc_native_inputs_v1 import load
torch.set_num_threads(6);torch.set_grad_enabled(False)
host=torch.load(ROOT/'host/ckpt.pt',weights_only=True,mmap=True)['model'];d=load(host);old=torch.load(ROOT/'artifacts/zu_pair_writer_hand_v1.pt',weights_only=True);roles=torch.load(ROOT/'artifacts/zm_hard_roles_v1.pt',weights_only=True);source=torch.load(ROOT/'experiments/zd1_projected_reader/circuit.pt',weights_only=True)['writer'];one=torch.zeros(769,dtype=torch.float64);one[-1]=1;row=roles['chosen'][0]['row'];rows=torch.cat((old['chosen']['rows'],torch.stack((128*row+8*one,128*row-8*one))));C=torch.zeros(11,36,dtype=torch.float64);C[:5,:34]=old['chosen']['coefficients'][:5];C[6:,:34]=old['chosen']['coefficients'][5:];C[5,:34]=-.5*old['chosen']['coefficients'][7];C[5,34]=1/16;C[5,35]=-1/16
